SELECT
    i.inspection_id,
    DATETIME(i.inspection_date, cmt.country_timezone) as inspection_date,
    DATETIME(i.inspection_last_modified, cmt.country_timezone) as inspection_last_modified,
    i.inspection_booking_code,
    i.inspection_forename,
    i.inspection_surname,
    i.inspection_email,
    i.inspection_phone,
    i.inspection_qc_score,
    i.inspection_leadsource,
    i.inspection_duration,
    i.inspector,
    DATETIME(i.deleted_at, cmt.country_timezone) as deleted_at,
    i.country_id,
    i.car_id,
    i.inspection_type,
    i.original_inspection_id,
    i.car_manufacturer,
    i.car_model,
    i.trim,
    i.transmission,
    i.year,
    i.inspection_number_of_comments,
    i.inspection_number_of_damages,
    i.address,
    i.chassis_number,
    i.chassis_color,
    i.invoice_type,
    i.invoice_vat,
    i.debt_tax,
    i.debt_other,
    i.registration_number,
    i.location,
    i.pickup_location,
    i.invoice_issued_by,
    i.invoice_origin,
    i.number_of_invoices,
    i.number_of_owners,
    i.environment_inspection_expire,
    i.environmental_class,
    i.is_purchased,
    i.is_auctioned,
    i.inspection_place_id,
    b.place_id as booking_place_id,
    i.auction_city,
    i.inspection_report,
    i.last_editor,
    i.qc_category_scores,
    i.non_matching_fields,
    DATETIME(i.start_time, cmt.country_timezone) as start_time,
    DATETIME(i.end_time, cmt.country_timezone) as end_time,
    i.config_id,
    i.mileage,
    i.inspection_number_of_images,
    i.color_body_part_map,
    i.galleries,
    `{{params.project_name}}.staging.getImageCount`(i.galleries) as image_count,
    `{{params.project_name}}.staging.getDamageCount`(i.galleries) as damage_count,
    i.inspection_group
FROM `{{params.project_name}}.staging.Inspections` i
INNER JOIN `{{params.project_name}}.staging.CountryMetadata` cmt using (country_id)
LEFT JOIN (select * except(dedup) from (
select *, row_number() over(partition by external_id order by booking_last_modified desc) as dedup from `{{params.project_name}}.staging.Bookings`
where deleted_at is null)
where dedup = 1) b on i.inspection_booking_code = b.external_id
where i.inspection_last_modified >= '{{params.start_ts}}' and i.inspection_last_modified < '{{params.end_ts}}'